	public static function activity_keys() {
		$ui = array( 'search', 'pin', 'arrow', 'arrowleft', 'check', 'chevron', 'chevrondown', 'phone', 'mail', 'file', 'photo', 'user', 'users', 'lock', 'clock', 'dashboard', 'send', 'upload', 'download', 'info', 'x', 'plus', 'minus', 'message', 'paperclip', 'kanban', 'list' );
		return array_values( array_diff( array_keys( self::all() ), $ui ) );
	}

	public static function inner( $key ) {
		$all = self::all();
		return isset( $all[ $key ] ) ? $all[ $key ] : $all['hammer'];
	}

	/**
	 * SVG complet, décoratif (aria-hidden).
	 *
	 * @param string $key   Clé.
	 * @param int    $size  Taille en px.
	 * @param string $class Classe CSS.
	 * @return string
	 */
	public static function svg( $key, $size = 20, $class = 'rn-icon' ) {
		return sprintf(
			'<svg class="%1$s" width="%2$d" height="%2$d" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">%3$s</svg>',
			esc_attr( $class ),
			(int) $size,
			self::inner( $key ) // Contenu statique interne, sûr.
		);
	}
}
